SELECT UTC_TIMESTAMP(3) observed_utc;
SELECT d.account_id,d.task_id,TIMESTAMPDIFF(SECOND,FROM_UNIXTIME(t.finished_at/1000),UTC_TIMESTAMP()) retained_after_task_end_seconds FROM account_creator_deletion d JOIN pull_task t ON t.id=d.task_id AND t.tenant_id=d.tenant_id;
SELECT account_id,task_id,group_execution_id,role_type,availability_status,released_at IS NOT NULL released,occupancy_key IS NOT NULL occupied,unavailable_reason_code FROM pull_task_group_account WHERE account_id IN (1038,1736,2755,2757) ORDER BY account_id,id;
SELECT a.id account_id,COUNT(DISTINCT p.id) bound_proxy_count,COUNT(DISTINCT c.id) active_credential_count,MAX(c.proxy_retain_until) proxy_retain_until FROM account a LEFT JOIN ip_proxy p ON p.bound_account_id=a.id AND p.tenant_id=a.tenant_id AND p.deleted_at IS NULL LEFT JOIN account_credential c ON c.account_id=a.id AND c.tenant_id=a.tenant_id AND c.deleted_at IS NULL WHERE a.id IN (1038,1736,2755,2757) GROUP BY a.id;
SELECT account_id,membership_status,COUNT(*) n FROM account_group_membership WHERE account_id IN (1038,1736,2755,2757) AND deleted_at IS NULL GROUP BY account_id,membership_status;
SELECT account_id,COUNT(*) n FROM wa_account_group_binding WHERE account_id IN (1038,1736,2755,2757) GROUP BY account_id;
SELECT account_id,COUNT(*) n FROM marketing_account_occupancy WHERE account_id IN (1038,1736,2755,2757) GROUP BY account_id;
SELECT a.account_id,t.task_status,COUNT(*) n FROM feed_task_account a JOIN feed_task t ON t.id=a.task_id AND t.tenant_id=a.tenant_id WHERE a.account_id IN (1038,1736,2755,2757) GROUP BY a.account_id,t.task_status;
SELECT a.account_id,t.run_status,COUNT(*) n FROM contact_friend_task_account a JOIN contact_friend_task t ON t.id=a.task_id AND t.tenant_id=a.tenant_id WHERE a.account_id IN (1038,1736,2755,2757) GROUP BY a.account_id,t.run_status;
SELECT a.account_id,raw_code,diagnosis_code,action_taken,COUNT(*) n,MIN(occurred_at) first_utc,MAX(occurred_at) last_utc FROM account_online_attempt_log a WHERE a.occurred_at>='2026-10-06 15:01:55' AND (a.account_id IN (1038,1736,2755,2757) OR raw_code IN (1001,1011)) GROUP BY a.account_id,raw_code,diagnosis_code,action_taken;
SELECT o.aggregate_id,o.command_type,o.status,COUNT(*) n,MIN(FROM_UNIXTIME(o.created_at/1000)) first_utc,MAX(FROM_UNIXTIME(o.created_at/1000)) last_utc FROM protocol_command_outbox o WHERE o.created_at>=1791302515000 AND o.aggregate_type='ACCOUNT' AND o.aggregate_id IN (1038,1736,2755,2757) GROUP BY o.aggregate_id,o.command_type,o.status;
SELECT COUNT(*) total_group_accounts,SUM(a.deleted_at IS NULL) active_accounts,SUM(a.deleted_at IS NULL AND s.login_state=1) db_online_accounts,SUM(a.deleted_at IS NULL AND NOT EXISTS(SELECT 1 FROM account_creator_deletion d WHERE d.account_id=a.id OR d.creator_phone=a.creator_deletion_identity_phone)) without_creator_reservation FROM account a LEFT JOIN account_state s ON s.account_id=a.id AND s.tenant_id=a.tenant_id WHERE a.tenant_id=1 AND a.account_group_id=702;
